stopBreathing() {
  if (this.breathingController) {
    this.breathingController.stop()
    this.breathingController = null
  }
},

// 入场序列动画：元素依次出现
playEntranceAnimation() {
  var page = this
  // 初始状态：所有元素透明
  var elements = ['timeSection', 'ringsSection', 'statusCard', 'btnEnter']
  elements.forEach(function(name) {
    var el = page.$element && page.$element(name)
    if (el) {
      el.style.opacity = '0'
      el.style.transform = 'translateY(20px)'
    }
  })

  // 依次动画出现，间隔 80ms
  elements.forEach(function(name, index) {
    setTimeout(function() {
      var el = page.$element && page.$element(name)
      if (el) {
        animate({
          duration: 350,
          easing: easeOutCubic,
          onFrame: function(progress) {
            var translateY = 20 * (1 - progress)
            el.style.transform = 'translateY(' + translateY + 'px)'
            el.style.opacity = String(progress)
          },
          onComplete: function() {
            el.style.transform = 'translateY(0px)'
            el.style.opacity = '1'
          }
        })
      }
    }, 100 + index * 80)
  })
},

