  var page = this
  this.sosPressStart = Date.now()
  this.sosProgress = 0
  this.sosHolding = true

  // 按钮缩放反馈
  if (e && e.target) buttonPress(e.target)

  // 进度条动画（1.5秒长按确认）
  this.sosProgressTimer = setInterval(function() {
    if (!page.sosHolding) return
    var elapsed = Date.now() - page.sosPressStart
    var pct = Math.min((elapsed / 1500) * 100, 100)
    page.sosProgress = pct

    // 最后 500ms 加速视觉反馈
    if (pct > 66) {
      page.sosClass = "sos-urgent"
    }

    // 长按完成，触发 SOS
    if (pct >= 100) {
      page.sosHolding = false
      clearInterval(page.sosProgressTimer)
      page.sosProgress = 0
      page.sosClass = "sos-normal"
      page.openAlert(createSosAlert())
    }
  }, 16)
},

onSosRelease(e) {
  // 释放按钮，取消长按
  this.sosHolding = false
  if (this.sosProgressTimer) {
    clearInterval(this.sosProgressTimer)
    this.sosProgressTimer = null
  }
  this.sosProgress = 0
  this.sosClass = "sos-normal"

  // 按钮弹回动画
  if (e && e.target) buttonRelease(e.target)
},

onSosCancel() {
  // 鼠标离开取消
  this.sosHolding = false
  if (this.sosProgressTimer) {
    clearInterval(this.sosProgressTimer)
    this.sosProgressTimer = null
  }
  this.sosProgress = 0
  this.sosClass = "sos-normal"
},

openAlert(a) {
  this.$app.$def.setCurrentAlert(a)
  router.push({ uri: "/pages/alert" })
},

