// ─── 页面入场动画 ──────────────────────────────────────

/**
 * Apple Watch 风格的页面入场动画
 * 元素从下方滑入 + 淡入，交错出现
 * @param {Object} page - 页面实例 (this)
 * @param {Array} elementIds - 元素 ID 数组
 * @param {Object} options - 配置选项
 */
export function pageEntrance(page, elementIds, options) {
  options = options || {}
  var stagger = options.stagger || 60
  var distance = options.distance || 16
  var duration = options.duration || 300
  var startDelay = options.startDelay || 50

  elementIds.forEach(function(id) {
    var el = page.$element && page.$element(id)
    if (el) {
      el.style.opacity = '0'
      el.style.transform = 'translateY(' + distance + 'px)'
    }
  })

  elementIds.forEach(function(id, index) {
    setTimeout(function() {
      var el = page.$element && page.$element(id)
      if (el) {
        animate({
          duration: duration,
          easing: easeOutCubic,
          onFrame: function(progress) {
            var translateY = distance * (1 - progress)
            el.style.transform = 'translateY(' + translateY + 'px)'
            el.style.opacity = String(progress)
          },
          onComplete: function() {
            el.style.transform = 'translateY(0px)'
            el.style.opacity = '1'
          }
        })
      }
    }, startDelay + index * stagger)
  })
}

/**
 * 列表项交错出现动画
 * @param {Object} page - 页面实例
 * @param {Array} elementIds - 元素 ID 数组
 * @param {Object} options - 配置选项
 */
export function listStagger(page, elementIds, options) {
  options = options || {}
  var stagger = options.stagger || 40
  var duration = options.duration || 250

  elementIds.forEach(function(id) {
    var el = page.$element && page.$element(id)
    if (el) {
      el.style.opacity = '0'
      el.style.transform = 'translateX(-12px)'
    }
  })

  elementIds.forEach(function(id, index) {
    setTimeout(function() {
      var el = page.$element && page.$element(id)
      if (el) {
        animate({
          duration: duration,
          easing: easeOutCubic,
          onFrame: function(progress) {
            var translateX = -12 * (1 - progress)
            el.style.transform = 'translateX(' + translateX + 'px)'
            el.style.opacity = String(progress)
          },
          onComplete: function() {
            el.style.transform = 'translateX(0px)'
            el.style.opacity = '1'
          }
        })
      }
    }, index * stagger)
  })
}

